// src/edgeWidths.ts
var EDGE_WIDTHS = [
  {
    value: "uniform",
    label: "Uniform",
    description: "Every link the same thickness."
  },
  {
    value: "walks",
    label: "By walks",
    description: "Thicker the more walks take a link, on the square root of its count against the busiest link in the cut. A graph without walks draws uniform."
  }
];
var MIN_FACTOR = 0.5;
var MAX_FACTOR = 4;
function busiestEdge(graph) {
  let most = 0;
  for (const edge of graph.edges) {
    most = Math.max(most, edge.pathIds?.length ?? 0);
  }
  return most;
}
function edgeWidthFactor(walks, busiest, edgeWidth) {
  if (edgeWidth === "uniform" || busiest === 0) {
    return 1;
  }
  return MIN_FACTOR + (MAX_FACTOR - MIN_FACTOR) * Math.sqrt(walks / busiest);
}

export {
  EDGE_WIDTHS,
  busiestEdge,
  edgeWidthFactor
};
