import {
  panSNHaplotype
} from "./chunk-2JL2JVZ2.js";

// src/nodeWidths.ts
var NODE_WIDTHS = [
  {
    value: "depth",
    label: "By depth",
    description: "Thicker the more paths carry a node, on the square root of its depth against the mean. A graph with one depth everywhere draws uniform."
  },
  {
    value: "frequency",
    label: "By frequency",
    description: "As wide as the share of haplotypes that pass a node, or its AF tag: full width at 100%, half at 50%, and wider where a haplotype passes it more than once."
  },
  {
    value: "uniform",
    label: "Uniform",
    description: "Every node the same thickness."
  }
];
var MIN_FACTOR = 0.3;
var MAX_FACTOR = 3;
var MIN_FREQUENCY_FACTOR = 0.05;
function meanDepth(graph) {
  let weighted = 0;
  let length = 0;
  for (const node of graph.nodes) {
    weighted += node.depth * node.length;
    length += node.length;
  }
  return length > 0 ? weighted / length : 0;
}
function haplotypeOf(path) {
  return path.sample === void 0 ? panSNHaplotype(path.name) ?? path.name : `${path.sample}#${path.haplotype ?? 0}`;
}
function haplotypeCount(graph) {
  return new Set((graph.paths ?? []).map(haplotypeOf)).size;
}
function nodeFrequency(node, haplotypes) {
  return node.frequency ?? (haplotypes > 0 ? node.depth / haplotypes : void 0);
}
function withFrequencies(graph, frequencies) {
  if (!frequencies) {
    return graph;
  }
  const nodes = graph.nodes.map((node) => {
    const frequency = frequencies[node.name];
    return frequency === void 0 ? node : { ...node, frequency };
  });
  return { ...graph, nodes };
}
function widthNorm(graph, nodeWidth) {
  return nodeWidth === "depth" ? meanDepth(graph) : nodeWidth === "frequency" ? haplotypeCount(graph) : 0;
}
function frequencyFactor(f) {
  return Math.min(MAX_FACTOR, Math.max(MIN_FREQUENCY_FACTOR, f));
}
function frequencyWidthFactor(node, haplotypes) {
  const f = nodeFrequency(node, haplotypes);
  return f === void 0 ? 1 : frequencyFactor(f);
}
function frequencyKey(contigThickness) {
  return [1, 0.5, 0.1].map((f) => ({
    label: `${f * 100}%`,
    widthPx: contigThickness * frequencyFactor(f)
  }));
}
function depthWidthFactor(node, mean) {
  if (!(mean > 0) || !(node.depth > 0)) {
    return 1;
  }
  return Math.min(
    MAX_FACTOR,
    Math.max(MIN_FACTOR, Math.sqrt(node.depth / mean))
  );
}
function nodeWidthPx(node, contigThickness, nodeWidth, norm) {
  return contigThickness * (nodeWidth === "depth" ? depthWidthFactor(node, norm) : nodeWidth === "frequency" ? frequencyWidthFactor(node, norm) : 1);
}
function maxNodeWidthPx(contigThickness, nodeWidth) {
  return contigThickness * (nodeWidth === "uniform" ? 1 : MAX_FACTOR);
}
var MIN_WALK_LANE_PX = 4;
function walkLaneWidthPx(width, lanes) {
  return Math.max(width / lanes, MIN_WALK_LANE_PX);
}
function nodeInk(graph, nodeById, contigThickness, nodeWidth, lanes = 0) {
  const norm = graph ? widthNorm(graph, nodeWidth) : 0;
  const reach = (width) => lanes > 0 ? walkLaneWidthPx(width, lanes) * lanes / 2 : width / 2;
  return {
    maxHalfWidthPx: reach(maxNodeWidthPx(contigThickness, nodeWidth)),
    halfWidthPx: (id) => {
      const node = nodeById?.get(id);
      return reach(
        node ? nodeWidthPx(node, contigThickness, nodeWidth, norm) : contigThickness
      );
    }
  };
}

export {
  NODE_WIDTHS,
  meanDepth,
  haplotypeCount,
  nodeFrequency,
  withFrequencies,
  widthNorm,
  frequencyKey,
  nodeWidthPx,
  maxNodeWidthPx,
  walkLaneWidthPx,
  nodeInk
};
