// src/overlayLabels.ts
var LABEL_PX = 11;
var LABEL_CHAR_PX = 6.2;
var LABEL_PAD = 4;
function labelWidth(text) {
  return text.length * LABEL_CHAR_PX + LABEL_PAD * 2;
}
function overlaps(a, b) {
  return a.x0 < b.x1 && a.x1 > b.x0 && a.y0 < b.y1 && a.y1 > b.y0;
}
function offFrame(box, frame) {
  return box.x1 <= 0 || box.x0 >= frame.width || box.y1 <= 0 || box.y0 >= frame.height;
}
function insideFrame(box, frame) {
  return box.x0 >= 0 && box.x1 <= frame.width && box.y0 >= 0 && box.y1 <= frame.height;
}
function occupancy(frame, reserved = []) {
  const placed = [...reserved];
  return (box) => {
    if (offFrame(box, frame) || placed.some((p) => overlaps(p, box))) {
      return false;
    }
    placed.push(box);
    return true;
  };
}
function placeLabels(candidates, frame, take) {
  const out = [];
  const row = LABEL_PX + LABEL_PAD * 2;
  const stackFrom = (c, text, from, direction) => {
    const w = labelWidth(text);
    let crowded = false;
    for (let tries = 0; tries <= (c.stack ?? 0); tries++) {
      const y = from + direction * tries * row;
      const box = {
        x0: c.x - w / 2,
        x1: c.x + w / 2,
        y0: y - LABEL_PX - LABEL_PAD,
        y1: y + LABEL_PAD
      };
      if (offFrame(box, frame)) {
        break;
      }
      if (insideFrame(box, frame) && (c.fits?.(box) ?? true)) {
        if (take(box)) {
          return { placed: { ...c, text, y, w }, crowded };
        }
        crowded = true;
      }
    }
    return { placed: void 0, crowded };
  };
  const place = (c, text) => {
    const first = stackFrom(c, text, c.y, c.y > frame.height / 2 ? -1 : 1);
    return first.placed ?? (c.flipY === void 0 || first.crowded ? void 0 : stackFrom(c, text, c.flipY, c.flipY < c.y ? -1 : 1).placed);
  };
  for (const c of candidates) {
    const placed = place(c, c.text) ?? (c.fallback === void 0 ? void 0 : place(c, c.fallback));
    if (placed) {
      out.push(placed);
    }
  }
  return out;
}

export {
  LABEL_PX,
  LABEL_CHAR_PX,
  LABEL_PAD,
  labelWidth,
  overlaps,
  occupancy,
  placeLabels
};
